inline const MapResourceCounts *map_resource_counts(const char *map_id) {
	for (const auto &r : kMapResourceCounts)
		if (std::strcmp(r.map_id, map_id) == 0) return &r;
	return nullptr;
}

// A grid's count at a map of tiles x tiles for players: linear between the sizes and
// player counts above, held at the ends.
inline int map_resource_count(const uint16_t (&grid)[4][3], float tiles, int players) {
	const float ts = tiles < 128.0f ? 0.0f : tiles > 512.0f ? 3.0f : (tiles - 128.0f) / 128.0f;
	const float ps = players <= 2 ? 0.0f : players >= 8 ? 2.0f : players <= 4 ? (players - 2) / 2.0f : 1.0f + (players - 4) / 4.0f;
	const int t0 = ts >= 3.0f ? 2 : (int)ts, p0 = ps >= 2.0f ? 1 : (int)ps;
	const float tf = ts - (float)t0, pf = ps - (float)p0;
	const float a = grid[t0][p0] + (grid[t0][p0 + 1] - grid[t0][p0]) * pf;
	const float b = grid[t0 + 1][p0] + (grid[t0 + 1][p0 + 1] - grid[t0 + 1][p0]) * pf;
	return (int)(a + (b - a) * tf + 0.5f);
}

